
const DBKEY='hawraz_offline_v1';
const EMPTY={schemaVersion:2,settings:{currency:'IRT',language:'fa',lowStock:3,backupReminderDays:7,theme:'teal',mode:'dark',fontScale:100,iconScale:100,background:'gradient',backgroundImage:'',invoiceTemplate:'classic',calendarType:'gregory',dateOrder:'ymd',iconStyle:'rounded',layout:'practical',navPosition:'side',navSide:'right',clockVisible:true,clockStyle:'digital',clockPosition:'header',clockColor:'#35d6c5',currency:'IRT',invoiceAccent:'#087e83',invoiceTitle:'فاکتور فروش',appRelease:'2026.10',developerName:'تیم توسعه هەوراز',companyName:'هەوراز',companyPhone:'',companyAddress:'',taxId:''},products:[],customers:[],orders:[],payments:[],expenses:[],accounts:[{id:'cash',name:'صندوق نقدی',type:'cash',opening:0}],tools:[],suppliers:[],reminders:[],tasks:[],ideas:[],waste:[],knowledge:[],projectArchive:[],audit:[]};
let db, page='dashboard', editId=null, editOrderId=null, navExpanded=false;
const $=id=>document.getElementById(id);
const uid=()=>crypto.randomUUID();
const today=()=>new Date().toISOString().slice(0,10);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>{const n=Number(v);if(!Number.isSafeInteger(n)||n<0)throw Error('مبلغ باید عدد صحیح و مثبت باشد.');return n};
const CURRENCIES={IRT:{label:'تومان',symbol:'تومان',locale:'fa-IR'},IRR:{label:'ریال',symbol:'ریال',locale:'fa-IR'},USD:{label:'دلار آمریکا',symbol:'$',locale:'en-US'},EUR:{label:'یورو',symbol:'€',locale:'de-DE'},GBP:{label:'پوند',symbol:'£',locale:'en-GB'},TRY:{label:'لیر ترکیه',symbol:'₺',locale:'tr-TR'},AED:{label:'درهم امارات',symbol:'د.إ',locale:'ar-AE'},CAD:{label:'دلار کانادا',symbol:'C$',locale:'en-CA'},AUD:{label:'دلار استرالیا',symbol:'A$',locale:'en-AU'},JPY:{label:'ین ژاپن',symbol:'¥',locale:'ja-JP'},CHF:{label:'فرانک سوئیس',symbol:'CHF',locale:'de-CH'},CNY:{label:'یوان چین',symbol:'¥',locale:'zh-CN'}};
const fmt=n=>{const c=CURRENCIES[db?.settings?.currency]||CURRENCIES.IRT;return `${Number(n||0).toLocaleString(c.locale,{maximumFractionDigits:2})} ${c.symbol}`};
const sum=(arr,fn)=>arr.reduce((a,x)=>a+Number(fn(x)||0),0);
const toast=m=>{const el=$('toast');el.textContent=translateText(m);el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2300)};
const save=async()=>{await new Promise((resolve,reject)=>{const tx=IDB.transaction('workspace','readwrite');tx.objectStore('workspace').put(db,'main');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('ذخیره‌سازی ناموفق'))});};
let IDB;
function openDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open(DBKEY,1);req.onupgradeneeded=()=>req.result.createObjectStore('workspace');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function init(){IDB=await openDB();db=await new Promise((resolve,reject)=>{const q=IDB.transaction('workspace','readonly').objectStore('workspace').get('main');q.onsuccess=()=>resolve({...structuredClone(EMPTY),...(q.result||{})});q.onerror=()=>reject(q.error)});Object.keys(EMPTY).forEach(k=>{if(!db[k])db[k]=structuredClone(EMPTY[k])});if(!db.settings)db.settings=structuredClone(EMPTY.settings);const legacyIconStyles={minimal:'square',heart:'rounded',cloud:'rounded'};if(legacyIconStyles[db.settings.iconStyle])db.settings.iconStyle=legacyIconStyles[db.settings.iconStyle];if(!['square','rounded','pill'].includes(db.settings.iconStyle))db.settings.iconStyle='rounded';if(!['practical','compact','fast'].includes(db.settings.layout))db.settings.layout='practical';if(!['classic','modern','minimal'].includes(db.settings.invoiceTemplate))db.settings.invoiceTemplate='classic';if(!db.tasks)db.tasks=[];['ideas','waste','knowledge','projectArchive'].forEach(k=>{if(!Array.isArray(db[k]))db[k]=[]});db.schemaVersion=2;if(!db.settings.authSalt||!db.settings.authHash){const h=await makePasswordHash('123454321');db.settings.authSalt=h.salt;db.settings.authHash=h.hash;db.settings.mustChangePassword=true;db.settings.authFailedCount=0;db.settings.authLockedUntil=0;await save()}else if(!db.settings.mustChangePassword&&await checkPassword('123454321')){db.settings.mustChangePassword=true;await save()}if(db.settings.authFailedCount===undefined)db.settings.authFailedCount=0;if(db.settings.authLockedUntil===undefined)db.settings.authLockedUntil=0;applyAppearance();if(sessionStorage.getItem('hawraz_unlocked')==='yes'&&!db.settings.mustChangePassword){render();armIdleLock()}else renderLock();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});}

const enc64=b=>btoa(String.fromCharCode(...new Uint8Array(b)));
async function makePasswordHash(password,saltText){const salt=saltText?Uint8Array.from(atob(saltText),c=>c.charCodeAt(0)):crypto.getRandomValues(new Uint8Array(16));const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt,iterations:210000,hash:'SHA-256'},material,256);return {salt:enc64(salt),hash:enc64(bits)}}
async function checkPassword(password){const h=await makePasswordHash(password,db.settings.authSalt);return h.hash===db.settings.authHash}
function renderLock(){document.querySelector('.lock-screen')?.remove();const el=document.createElement('div');el.className='lock-screen';el.innerHTML=`<form id="unlock-form" class="lock-card"><img src="./icon.svg" alt="HAWRAZ"><small>WORKSHOP MANAGEMENT</small><h1>${db.settings.mustChangePassword?'تغییر اجباری رمز ورود':'ورود به هەوراز'}</h1><p>${db.settings.mustChangePassword?'رمز پیش‌فرض ناامن است. ابتدا رمز جدید و شخصی تعیین کن.':'برای ورود، رمز عبور را وارد کن.'}</p><input name="password" type="password" autocomplete="current-password" placeholder="${db.settings.mustChangePassword?'رمز فعلی':'رمز عبور'}" required autofocus>${db.settings.mustChangePassword?'<input name="newPassword" type="password" autocomplete="new-password" minlength="8" placeholder="رمز جدید (حداقل ۸ نویسه)" required><input name="confirmPassword" type="password" autocomplete="new-password" minlength="8" placeholder="تکرار رمز جدید" required>':''}<button class="primary">${db.settings.mustChangePassword?'ثبت رمز جدید':'ورود'}</button><small class="muted">قفل محلی دستگاه · نه احراز هویت سروری</small></form>`;document.body.appendChild(el);$('unlock-form').onsubmit=async e=>{e.preventDefault();const d=formData(e.currentTarget),now=Date.now();if(Number(db.settings.authLockedUntil||0)>now){toast('به‌دلیل تلاش‌های ناموفق، ورود موقتاً قفل است.');return}if(!await checkPassword(d.password)){db.settings.authFailedCount=Number(db.settings.authFailedCount||0)+1;if(db.settings.authFailedCount>=5){db.settings.authLockedUntil=Date.now()+60000;db.settings.authFailedCount=0;toast('۵ تلاش ناموفق؛ ورود برای ۶۰ ثانیه قفل شد.')}else toast('رمز عبور نادرست است. تلاش باقی‌مانده: '+(5-db.settings.authFailedCount));await save();return}if(db.settings.mustChangePassword){if(String(d.newPassword||'').length<8)return toast('رمز جدید باید حداقل ۸ نویسه باشد.');if(d.newPassword!==d.confirmPassword)return toast('تکرار رمز جدید یکسان نیست.');const h=await makePasswordHash(d.newPassword);db.settings.authSalt=h.salt;db.settings.authHash=h.hash;db.settings.mustChangePassword=false}db.settings.authFailedCount=0;db.settings.authLockedUntil=0;await save();sessionStorage.setItem('hawraz_unlocked','yes');el.remove();render();armIdleLock()};}
let idleLockTimer=null;
function armIdleLock(){clearTimeout(idleLockTimer);idleLockTimer=setTimeout(()=>{sessionStorage.removeItem('hawraz_unlocked');renderLock();toast('برای امنیت، نشست پس از ۱۵ دقیقه بی‌فعالیتی قفل شد.')},15*60*1000)}
['pointerdown','keydown','touchstart'].forEach(ev=>window.addEventListener(ev,()=>{if(sessionStorage.getItem('hawraz_unlocked')==='yes')armIdleLock()},{passive:true}));
function lockApp(){clearTimeout(idleLockTimer);sessionStorage.removeItem('hawraz_unlocked');renderLock()}

function applyAppearance(){if(!db?.settings)return;const palettes={teal:['#35d6c5','#087e83','#176b9c'],blue:['#69a9ff','#245cb5','#173e80'],purple:['#c4a3ff','#7046b5','#4b337f'],amber:['#f5c66b','#a86a14','#70460e'],rose:['#ff9db7','#ad3b65','#762847'],emerald:['#6ee7a8','#16845b','#10543d']};const p=palettes[db.settings.theme]||palettes.teal;document.documentElement.style.setProperty('--cyan',p[0]);document.documentElement.style.setProperty('--accent-a',p[1]);document.documentElement.style.setProperty('--accent-b',p[2]);document.documentElement.style.setProperty('--font-scale',(Number(db.settings.fontScale)||100)/100);document.documentElement.style.setProperty('--icon-scale',(Number(db.settings.iconScale)||100)/100);const mode=db.settings.mode||'dark';document.body.classList.toggle('light-mode',mode==='light');document.body.dataset.mode=mode;const bgs={gradient:'radial-gradient(ellipse at 80% 0,#164052,transparent 38%),#081522',plain:'#081522',forest:'radial-gradient(ellipse at 80% 0,#234b3c,transparent 38%),#0b1b17',sand:'radial-gradient(ellipse at 80% 0,#66543b,transparent 38%),#211b14'};document.body.style.background=mode==='light'?'#edf3f7':(bgs[db.settings.background]||bgs.gradient);if(db.settings.backgroundImage){document.body.style.backgroundImage=`linear-gradient(#081522aa,#081522cc),url(\"${db.settings.backgroundImage}\")`;document.body.style.backgroundSize='cover';document.body.style.backgroundPosition='center center';document.body.style.backgroundAttachment='fixed'}else{document.body.style.backgroundImage='';document.body.style.backgroundSize='';document.body.style.backgroundPosition='';document.body.style.backgroundAttachment=''}document.body.classList.remove('icon-style-rounded','icon-style-square','icon-style-minimal','icon-style-heart','icon-style-cloud','icon-style-pill');const shape=['square','rounded','pill'].includes(db.settings.iconStyle)?db.settings.iconStyle:'rounded';document.body.classList.add('icon-style-'+shape);document.body.classList.remove('layout-practical','layout-compact','layout-fast','nav-top','nav-left','nav-right');document.body.classList.add('layout-'+(db.settings.layout||'practical'));document.body.classList.add('nav-'+(db.settings.navPosition==='top'?'top':(db.settings.navSide||'right')));document.documentElement.style.setProperty('--clock-color',db.settings.clockColor||p[0]);} 

