function translateDom(){const lang=db.settings.language||'fa';const rtl=['fa','ar','ku'].includes(lang);const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let n;while(n=walker.nextNode()){if(n.parentElement?.closest('script,style,textarea,[contenteditable="true"],.no-translate'))continue;if(n.parentElement?.tagName==='OPTION')continue;if(n.parentElement?.tagName==='INPUT'&&['button','submit','reset','hidden'].includes((n.parentElement.type||'').toLowerCase()))continue;if(n.parentElement?.dataset?.i18nSkip==='true')continue;if(n.__hawrazOriginal===undefined)n.__hawrazOriginal=n.nodeValue;const original=n.__hawrazOriginal;const translated=translateText(original,lang);if(n.nodeValue!==translated)n.nodeValue=translated;}document.querySelectorAll('[placeholder],[aria-label],[title],[value]').forEach(el=>['placeholder','aria-label','title'].forEach(a=>{if(!el.hasAttribute(a))return;const key='hawrazOriginal'+a;if(el.dataset[key]===undefined)el.dataset[key]=el.getAttribute(a);const original=el.dataset[key];const translated=translateText(original,lang);if(el.getAttribute(a)!==translated)el.setAttribute(a,translated)}));document.querySelectorAll('input[type=button],input[type=submit],input[type=reset]').forEach(el=>{if(el.dataset.hawrazOriginalValue===undefined)el.dataset.hawrazOriginalValue=el.value;el.value=translateText(el.dataset.hawrazOriginalValue,lang)});document.querySelectorAll('option').forEach(el=>{if(el.dataset.originalText===undefined)el.dataset.originalText=el.textContent;const translated=translateText(el.dataset.originalText,lang);if(el.textContent!==translated)el.textContent=translated});document.documentElement.lang=lang;document.documentElement.dir=rtl?'rtl':'ltr';document.title=translateText('HAWRAZ | هەوراز',lang);document.body.dataset.language=lang;}
function printCurrent(){window.print()}
function drawReportChart(){const c=$('report-chart');if(!c)return;const rect=c.getBoundingClientRect(),cssW=Math.max(320,Math.floor(rect.width||600)),cssH=270,dpr=Math.max(1,window.devicePixelRatio||1);if(c.width!==Math.floor(cssW*dpr)||c.height!==Math.floor(cssH*dpr)){c.width=Math.floor(cssW*dpr);c.height=Math.floor(cssH*dpr)}c.style.height=cssH+'px';const ctx=c.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);const type=$('chart-type')?.value||'bar',metric=$('chart-metric')?.value||'sales',limit=Number($('chart-count')?.value||8),rows=db.orders.filter(o=>o.status!=='cancelled').slice(-limit);const vals=rows.map(o=>({label:String(o.code||'').slice(-4)||'—',value:Math.max(0,Number(metric==='profit'?(o.profit??(Number(o.total||0)-Number(o.productionCost||0))):metric==='cost'?(o.productionCost||0):(o.total||0))||0)}));ctx.clearRect(0,0,cssW,cssH);ctx.fillStyle=getComputedStyle(document.documentElement).getPropertyValue('--text').trim()||'#a8bec9';ctx.font='12px Tahoma';ctx.fillText(metric==='profit'?'سود سفارش‌ها':metric==='cost'?'هزینه ساخت سفارش‌ها':'فروش سفارش‌ها',16,20);if(!vals.length){ctx.fillStyle='#91aab8';ctx.font='14px Tahoma';ctx.textAlign='center';ctx.fillText('هنوز سفارشی برای نمایش نمودار ثبت نشده است.',cssW/2,cssH/2);ctx.textAlign='start';return}const left=42,right=cssW-18,top=42,bottom=cssH-34,plotW=right-left,plotH=bottom-top,max=Math.max(1,...vals.map(x=>x.value)),color=getComputedStyle(document.documentElement).getPropertyValue('--cyan').trim()||'#35d6c5';ctx.strokeStyle='rgba(145,170,184,.22)';ctx.lineWidth=1;for(let i=0;i<5;i++){const y=top+i*plotH/4;ctx.beginPath();ctx.moveTo(left,y);ctx.lineTo(right,y);ctx.stroke()}if(type==='pie'){const positive=vals.filter(v=>v.value>0),total=positive.reduce((a,x)=>a+x.value,0);if(!total){ctx.fillStyle='#91aab8';ctx.textAlign='center';ctx.fillText('مقادیر این شاخص صفر است.',cssW/2,cssH/2);ctx.textAlign='start';return}let a=-Math.PI/2;const cx=cssW/2,cy=top+plotH/2,r=Math.min(plotH/2-4,plotW/3);positive.forEach((v,i)=>{const b=a+v.value/total*Math.PI*2;ctx.beginPath();ctx.moveTo(cx,cy);ctx.arc(cx,cy,r,a,b);ctx.closePath();ctx.fillStyle=`hsl(${165+i*39} 62% 53%)`;ctx.fill();a=b})}else if(type==='line'){ctx.beginPath();vals.forEach((v,i)=>{const x=left+(i+.5)*plotW/vals.length,y=bottom-v.value/max*plotH;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.strokeStyle=color;ctx.lineWidth=3;ctx.stroke();vals.forEach((v,i)=>{const x=left+(i+.5)*plotW/vals.length,y=bottom-v.value/max*plotH;ctx.beginPath();ctx.arc(x,y,4,0,Math.PI*2);ctx.fillStyle=color;ctx.fill();ctx.fillStyle='#9bb2bd';ctx.font='10px Tahoma';ctx.textAlign='center';ctx.fillText(v.label,x,cssH-12)})}else{const slot=plotW/vals.length,w=Math.max(4,Math.min(46,slot*.66));vals.forEach((v,i)=>{const h=v.value/max*(plotH-5),x=left+i*slot+(slot-w)/2,y=bottom-h;ctx.fillStyle=color;ctx.fillRect(x,y,w,h);ctx.fillStyle='#9bb2bd';ctx.font='10px Tahoma';ctx.textAlign='center';ctx.fillText(v.label,x+w/2,cssH-12)})}ctx.textAlign='start'}

function audit(action,kind,id,detail=''){db.audit.unshift({id:uid(),at:new Date().toISOString(),action,kind,recordId:id,detail});db.audit=db.audit.slice(0,2000)}
function orderTotal(o){return Number(o.total||0)}
function paidFor(customerId){return sum(db.payments.filter(p=>p.customerId===customerId&&p.kind==='receipt'),p=>p.amount)-sum(db.payments.filter(p=>p.customerId===customerId&&p.kind==='refund'),p=>p.amount)}
function customerOrders(id){return db.orders.filter(o=>o.customerId===id&&o.status!=='cancelled')}
function customerBalance(id){return sum(customerOrders(id),o=>o.total)-paidFor(id)}
function accountBalance(id){const a=db.accounts.find(x=>x.id===id);return Number(a?.opening||0)+sum(db.payments.filter(p=>p.accountId===id),p=>p.kind==='receipt'?p.amount:p.kind==='refund'?-p.amount:p.kind==='deposit'?p.amount:p.kind==='withdrawal'?-p.amount:0)-sum(db.expenses.filter(x=>x.accountId===id),x=>x.amount)}
function statusName(s){return ({registered:'ثبت‌شده',production:'در حال ساخت',ready:'آماده تحویل',delivered:'تحویل‌شده',cancelled:'لغوشده'})[s]||s}
function table(head,rows){return rows.length?`<div class="tablewrap"><table><thead><tr>${head.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x??'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:`<div class="empty">هنوز اطلاعاتی ثبت نشده است.</div>`}
function stat(label,value){return `<article class="stat"><span>${label}</span><strong>${value}</strong></article>`}
function panel(title,body){return `<section class="panel"><h2>${title}</h2>${body}</section>`}
function field(label,name,type='text',required=false,extra=''){return `<label>${label}<input name="${name}" type="${type}" ${required?'required':''} ${extra}></label>`}
function select(label,name,options,required=false){return `<label>${label}<select name="${name}" ${required?'required':''}>${options.map(o=>`<option value="${esc(o[0])}">${esc(o[1])}</option>`).join('')}</select></label>`}
function form(id,fields,button='ذخیره'){return `<form class="form" id="${id}">${fields}<div class="span2"><button class="primary" type="submit">${button}</button> <button type="button" class="ghost" data-clear="${id}">پاک‌کردن فرم</button></div></form>`}
