function safeCalc(expression){if(!/^[0-9+*/().% -]+$/.test(expression))throw Error('عبارت نامعتبر');const tokens=expression.match(/\d+(?:\.\d+)?|[()+*/-]/g)||[];let i=0;function atom(){const t=tokens[i++];if(t==='('){const v=add();if(tokens[i++]!==')')throw Error();return v}if(t==='-')return -atom();const n=Number(t);if(!Number.isFinite(n))throw Error();return n}function mul(){let v=atom();while(tokens[i]==='*'||tokens[i]==='/'){const op=tokens[i++],n=atom();v=op==='*'?v*n:v/n}return v}function add(){let v=mul();while(tokens[i]==='+'||tokens[i]==='-'){const op=tokens[i++],n=mul();v=op==='+'?v+n:v-n}return v}const out=add();if(i!==tokens.length||!Number.isFinite(out))throw Error();return out}
function mountUtilityWidgets(){let clock=$('hawraz-clock');if(!clock){clock=document.createElement('div');clock.id='hawraz-clock';document.body.appendChild(clock)}clock.style.display=db.settings.clockVisible===false?'none':'block';clock.dataset.position=db.settings.clockPosition||'header';clock.style.color=db.settings.clockColor||'var(--cyan)';if(clock.dataset.position==='header'){clock.style.position='static';document.querySelector('main header')?.appendChild(clock)}else{clock.style.position='fixed';document.body.appendChild(clock)}const tick=()=>{if(!document.body.contains(clock))return;const d=new Date(),date=d.toLocaleDateString(document.documentElement.lang||'fa-IR'),time=d.toLocaleTimeString(document.documentElement.lang||'fa-IR',{hour:'2-digit',minute:'2-digit',second:'2-digit'});if(db.settings.clockStyle==='analog'){const h=d.getHours()%12,m=d.getMinutes(),sec=d.getSeconds();clock.innerHTML=`<span class="analog-clock" role="img" aria-label="${esc(time)}"><i class="hand hour" style="transform:rotate(${h*30+m*.5}deg)"></i><i class="hand minute" style="transform:rotate(${m*6}deg)"></i><i class="hand second" style="transform:rotate(${sec*6}deg)"></i></span><span>${date}</span>`}else clock.textContent=db.settings.clockStyle==='date'?date:db.settings.clockStyle==='minimal'?`${time} · ${date}`:`◷ ${time}  |  ${date}`};tick();if(!clock.dataset.timer){clock.dataset.timer='1';setInterval(tick,1000)}let calc=$('hawraz-calc');if(!calc){calc=document.createElement('div');calc.id='hawraz-calc';calc.innerHTML=`<button id="calc-toggle" class="primary" aria-label="ماشین حساب">⌗</button><div id="calc-panel" hidden><div class="calc-head"><b>ماشین‌حساب سریع</b><button id="calc-close" class="ghost">×</button></div><input id="calc-display" value="0" readonly><div class="calc-keys">${['7','8','9','/','4','5','6','*','1','2','3','-','0','.','=','+','C','⌫','%','√'].map(k=>`<button class="ghost" data-calc="${k}">${k}</button>`).join('')}</div></div>`;document.body.appendChild(calc);let expr='';const display=()=>{$('calc-display').value=expr||'0'};calc.addEventListener('click',e=>{if(e.target.id==='calc-toggle'){$('calc-panel').hidden=!$('calc-panel').hidden;return}if(e.target.id==='calc-close'){$('calc-panel').hidden=true;return}const k=e.target.dataset.calc;if(!k)return;if(k==='C')expr='';else if(k==='⌫')expr=expr.slice(0,-1);else if(k==='√'){try{expr=String(Math.sqrt(Number(expr)||0))}catch{expr=''}}else if(k==='%'){try{expr=String(safeCalc(expr)/100)}catch{expr='خطا'}}else if(k==='='){try{if(!/^[0-9+*/().% -]+$/.test(expr))throw Error();expr=String(Function('"use strict";return ('+expr+')')());if(!Number.isFinite(Number(expr)))throw Error()}catch{expr='خطا'}}else expr+=k;display()})}}
function bind(){
 if(page==='search'){const inp=$('global-search'),cat=$('search-category');inp?.addEventListener('input',drawSearchResults);cat?.addEventListener('change',drawSearchResults);$('clear-search')?.addEventListener('click',()=>{inp.value='';cat.value='all';drawSearchResults();inp.focus()});$('search-results')?.addEventListener('click',e=>{const b=e.target.closest('[data-search-kind]');if(!b)return;const map={products:'products',customers:'customers',orders:'orders',expenses:'expenses',suppliers:'suppliers',tools:'tools',tasks:'tasks',reminders:'reminders',ideas:'ideas',waste:'waste',knowledge:'knowledge',archive:'archive'};page=map[b.dataset.searchKind]||'dashboard';editId=null;editOrderId=null;render();toast('بخش مرتبط باز شد؛ برای یافتن مورد، فهرست همان بخش را بررسی کن.')});}
 $('nav').onclick=e=>{const more=e.target.closest('[data-nav-more]');if(more){navExpanded=!navExpanded;nav();return}const b=e.target.closest('[data-page]');if(b){page=b.dataset.page;editId=null;editOrderId=null;render()}};
 $('view').addEventListener('change',async e=>{if(e.target.id==='background-image-file'&&e.target.files?.[0]){const file=e.target.files[0];if(!file.type.startsWith('image/'))return toast('لطفاً یک فایل تصویری انتخاب کن.');if(file.size>5*1024*1024)return toast('حجم تصویر باید کمتر از ۵ مگابایت باشد.');try{const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});db.settings.backgroundImage=data;await save();applyAppearance();const preview=$('background-image-preview');if(preview)preview.innerHTML=`<img src="${data}" alt="پیش‌نمایش پس‌زمینه">`;toast('تصویر پس‌زمینه ذخیره شد.')}catch(err){toast('ذخیره تصویر انجام نشد.')}}});
 $('view').addEventListener('click',async e=>{if(e.target.closest('#background-image-reset')){db.settings.backgroundImage='';await save();applyAppearance();const preview=$('background-image-preview');if(preview)preview.textContent='بدون تصویر دلخواه';const f=$('background-image-file');if(f)f.value='';toast('پس‌زمینه پیش‌فرض فعال شد.')}});

 $('view').onclick=async e=>{
  const b=e.target.closest('button');if(!b)return;
  if(b.dataset.clear){$(b.dataset.clear)?.reset();return}
  if(b.dataset.go){page=b.dataset.go;render();return}
  if(b.dataset.removeKind){const key=b.dataset.removeKind,id=b.dataset.removeId;if(!['ideas','waste','knowledge','projectArchive'].includes(key))return;if(confirm('این مورد حذف شود؟')){db[key]=(db[key]||[]).filter(x=>x.id!==id);audit('delete',key,id);await save();render()}return}
  if(b.dataset.wasteUsed){const item=(db.waste||[]).find(x=>x.id===b.dataset.wasteUsed);if(item){item.used=!item.used;audit('update','waste',item.id,item.used?'مصرف شد':'بازگشت به فهرست');await save();render()}return}
  if(b.dataset.editOrder){editOrderId=b.dataset.editOrder;page='orders';render();return}
  if(b.dataset.deleteOrder){const o=db.orders.find(x=>x.id===b.dataset.deleteOrder);if(!o)return;if(!confirm(`سفارش ${o.code||''} حذف شود؟ پرداخت‌های مرتبط حذف نمی‌شوند تا سابقه مالی حفظ شود.`))return;if(o.productId&&o.status!=='cancelled'){const p=db.products.find(x=>x.id===o.productId);if(p)p.quantity=Number(p.quantity||0)+Number(o.quantity||0)}db.orders=db.orders.filter(x=>x.id!==o.id);db.payments.forEach(p=>{if(p.orderId===o.id)p.orderId=''});if(editOrderId===o.id)editOrderId=null;audit('delete','order',o.id,o.code||'');await save();render();toast('سفارش حذف شد؛ سوابق پرداخت حفظ شدند.');return}
  if(b.dataset.taskDone){const t=db.tasks.find(x=>x.id===b.dataset.taskDone);if(t){t.status=t.status==='done'?'open':t.status==='open'?'doing':'done';await save();render()}return}
  if(b.dataset.taskDel){if(confirm('این کار حذف شود؟')){db.tasks=db.tasks.filter(x=>x.id!==b.dataset.taskDel);await save();render()}return}
  if(b.dataset.edit){const kind=b.dataset.edit,id=b.dataset.id;const arr={product:db.products,customer:db.customers}[kind];const item=arr.find(x=>x.id===id);if(!item)return;const f=$(kind+'-form');Object.entries(item).forEach(([k,v])=>{if(f.elements[k])f.elements[k].value=v});editId=id;toast('اطلاعات برای ویرایش در فرم قرار گرفت.');return}
  if(b.dataset.del==='product'){const p=db.products.find(x=>x.id===b.dataset.id);if(db.orders.some(o=>o.productId===p.id))return toast('این محصول در سفارش‌ها استفاده شده و حذف نمی‌شود.');if(confirm('محصول حذف شود؟')){db.products=db.products.filter(x=>x.id!==p.id);audit('delete','product',p.id);await save();render()}return}
  if(b.dataset.del==='customer'){const c=db.customers.find(x=>x.id===b.dataset.id);if(!c)return;if(db.orders.some(o=>o.customerId===c.id)||db.payments.some(p=>p.customerId===c.id))return toast('این مشتری سفارش یا سابقه پرداخت دارد؛ برای حفظ سوابق مالی حذف نمی‌شود.');if(confirm(`مشتری «${c.name}» حذف شود؟ این کار قابل بازگشت نیست.`)){db.customers=db.customers.filter(x=>x.id!==c.id);audit('delete','customer',c.id,c.name||'');await save();render();toast('مشتری حذف شد.')}return}
  if(b.dataset.del==='supplier'){const s=db.suppliers.find(x=>x.id===b.dataset.id);if(!s)return;if(confirm(`فروشنده «${s.name}» حذف شود؟ این کار قابل بازگشت نیست.`)){db.suppliers=db.suppliers.filter(x=>x.id!==s.id);audit('delete','supplier',s.id,s.name||'');await save();render();toast('فروشنده حذف شد.')}return}
  if(b.dataset.del==='account'){if(db.payments.some(p=>p.accountId===b.dataset.id)||db.expenses.some(x=>x.accountId===b.dataset.id))return toast('این حساب سابقه تراکنش دارد و حذف نمی‌شود.');if(confirm('حساب حذف شود؟')){db.accounts=db.accounts.filter(a=>a.id!==b.dataset.id);await save();render()}return}
  if(b.dataset.status){const o=db.orders.find(x=>x.id===b.dataset.status);const statuses=['registered','production','ready','delivered','cancelled'];const next=statuses[(statuses.indexOf(o.status)+1)%statuses.length];if(next==='cancelled'&&db.payments.some(p=>p.customerId===o.customerId&&p.description?.includes(o.code)))return toast('برای این سفارش پرداخت ثبت شده؛ ابتدا وضعیت مالی آن را بررسی کن.');if(next==='cancelled'&& !confirm('سفارش لغو شود؟ موجودی محصول به انبار برمی‌گردد.'))return;if(next==='cancelled'&&o.productId){const p=db.products.find(x=>x.id===o.productId);if(p)p.quantity+=o.quantity}if(o.status==='cancelled'&&next!=='cancelled'&&o.productId){const p=db.products.find(x=>x.id===o.productId);if(p&&p.quantity<o.quantity)return toast('موجودی کافی برای فعال‌کردن دوباره سفارش وجود ندارد.');if(p)p.quantity-=o.quantity}o.status=next;audit('status-change','order',o.id,next);await save();render();return}
  if(b.dataset.done){const x=db.reminders.find(x=>x.id===b.dataset.done);x.done=!x.done;await save();render();return}
  if(b.dataset.invoice){const o=db.orders.find(x=>x.id===b.dataset.invoice);printInvoice(o);return}
  if(b.dataset.csv)csv(b.dataset.csv);
 };
 const handlers={
 'product-form':async d=>{const p={id:editId||uid(),...d,quantity:num(d.quantity),buyPrice:num(d.buyPrice),sellPrice:num(d.sellPrice),updatedAt:new Date().toISOString()};if(editId){const i=db.products.findIndex(x=>x.id===editId);db.products[i]=p;audit('update','product',p.id)}else{db.products.push(p);audit('create','product',p.id)}editId=null;},
 'customer-form':async d=>{const c={id:editId||uid(),...d,updatedAt:new Date().toISOString()};if(editId){db.customers[db.customers.findIndex(x=>x.id===editId)]=c;audit('update','customer',c.id)}else{db.customers.push(c);audit('create','customer',c.id)}editId=null;},
 'order-form':async d=>{const items=JSON.parse(d.lineItems||'[]').filter(x=>x.description||Number(x.unitPrice)>0);if(!items.length)throw Error('حداقل یک ردیف کالا یا خدمات وارد کن.');const subtotal=items.reduce((a,x)=>a+Number(x.quantity||0)*Number(x.unitPrice||0),0),qty=items.reduce((a,x)=>a+Number(x.quantity||0),0),unit=qty?Math.round(subtotal/qty):0,pct=Math.min(100,Math.max(0,Number(d.discountPercent||0))),discount=Math.round(subtotal*pct/100),total=subtotal-discount,productionCost=num(d.productionCost||0);if(!Number.isSafeInteger(total)||total<0)throw Error('مبلغ نهایی نامعتبر است.');if(!db.customers.some(c=>c.id===d.customerId))throw Error('مشتری را انتخاب کن.');const old=editOrderId?db.orders.find(x=>x.id===editOrderId):null;if(!old&&d.status==='cancelled')throw Error('سفارش جدید را نمی‌توان با وضعیت لغوشده ثبت کرد.');if(old?.status==='cancelled')throw Error('سفارش لغوشده را ویرایش نکن؛ سفارش تازه بساز.');if(old&&old.customerId!==d.customerId&&db.payments.some(x=>x.orderId===old.id||x.description?.includes(old.code)))throw Error('این سفارش پرداخت مرتبط دارد؛ مشتری آن را تغییر نده.');if(old?.productId){const op=db.products.find(x=>x.id===old.productId);if(op)op.quantity+=old.quantity}const p=db.products.find(x=>x.id===d.productId);if(p&&p.quantity<qty){if(old?.productId){const op=db.products.find(x=>x.id===old.productId);if(op)op.quantity-=old.quantity}throw Error('موجودی کافی نیست.')}const paid=num(d.initialPayment||0);if(!old&&paid>total)throw Error('پیش‌پرداخت از مبلغ سفارش بیشتر است.');if(p&&d.status!=='cancelled')p.quantity-=qty;const o={...(old||{}),id:old?.id||uid(),code:old?.code||'HZ-'+Date.now().toString().slice(-8),customerId:d.customerId,productId:d.productId||null,title:d.title,items,quantity:qty,unitPrice:unit,subtotal,discountPercent:pct,discount,total,productionCost,profit:total-productionCost,orderDate:d.orderDate||today(),dueDate:d.dueDate,status:d.status||'registered',createdAt:old?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};if(old){db.orders[db.orders.findIndex(x=>x.id===old.id)]=o;audit('update','order',o.id)}else{db.orders.push(o);if(paid)db.payments.push({id:uid(),customerId:o.customerId,accountId:'cash',kind:'receipt',amount:paid,date:today(),description:'پیش‌پرداخت سفارش '+o.code});audit('create','order',o.id)}editOrderId=null;},
 'payment-form':async d=>{const amount=num(d.amount);if(!db.customers.some(c=>c.id===d.customerId))throw Error('مشتری نامعتبر است.');if(!db.accounts.some(a=>a.id===d.accountId))throw Error('حساب نامعتبر است.');if(d.kind==='refund'&&amount>Math.max(0,-customerBalance(d.customerId)))throw Error('مبلغ بازپرداخت از بستانکاری مشتری بیشتر است.');const linked=d.orderId?db.orders.find(o=>o.id===d.orderId):null;if(linked&&linked.customerId!==d.customerId)throw Error('سفارش انتخابی متعلق به این مشتری نیست.');db.payments.push({id:uid(),...d,amount,date:d.date||today(),description:[d.description,linked?.code].filter(Boolean).join(' · ')});audit('create','payment',d.id||'new')},
 'account-form':async d=>{db.accounts.push({id:uid(),...d,opening:num(d.opening||0)});audit('create','account',d.name)},
 'expense-form':async d=>{const amount=num(d.amount);if(accountBalance(d.accountId)<amount)throw Error('موجودی حساب برای این هزینه کافی نیست.');db.expenses.push({id:uid(),...d,amount});audit('create','expense',d.title)},
 'tool-form':async d=>{db.tools.push({id:uid(),...d,price:num(d.price||0)});audit('create','tool',d.name)},
 'supplier-form':async d=>{db.suppliers.push({id:uid(),...d});audit('create','supplier',d.name)},
 'reminder-form':async d=>{db.reminders.push({id:uid(),...d,done:false});audit('create','reminder',d.title)},
 'task-form':async d=>{db.tasks.push({id:uid(),...d,createdAt:new Date().toISOString()});audit('create','task',d.title)},
 'idea-form':async d=>{db.ideas.push({id:uid(),...d,date:today(),createdAt:new Date().toISOString()});audit('create','idea',d.title)},
 'waste-form':async d=>{const quantity=Number(d.quantity),value=num(d.value||0);if(!Number.isFinite(quantity)||quantity<=0)throw Error('مقدار باید بیشتر از صفر باشد.');db.waste.push({id:uid(),...d,quantity,value,used:false,date:today()});audit('create','waste',d.name)},
 'knowledge-form':async d=>{db.knowledge.push({id:uid(),...d,date:today(),updatedAt:new Date().toISOString()});audit('create','knowledge',d.title)},
 'archive-form':async d=>{const hours=Number(d.hours||0);if(!Number.isFinite(hours)||hours<0)throw Error('مدت ساخت معتبر نیست.');db.projectArchive.push({id:uid(),...d,cost:num(d.cost||0),hours,createdAt:new Date().toISOString()});audit('create','project-archive',d.title)},
 'settings-form':async d=>{db.settings.currency=d.currency;db.settings.lowStock=num(d.lowStock);db.settings.language=d.language;db.settings.theme=d.theme;db.settings.mode=d.mode;db.settings.background=d.background;db.settings.iconStyle=['square','rounded','pill'].includes(d.iconStyle)?d.iconStyle:'rounded';db.settings.layout=d.layout;db.settings.invoiceTemplate=['classic','modern','minimal'].includes(d.invoiceTemplate)?d.invoiceTemplate:'classic';navExpanded=false;db.settings.navPosition=d.navPosition;db.settings.navSide=d.navSide;db.settings.fontScale=num(d.fontScale);db.settings.iconScale=num(d.iconScale);db.settings.clockVisible=!!d.clockVisible;db.settings.clockStyle=d.clockStyle;db.settings.clockPosition=d.clockPosition;db.settings.clockColor=d.clockColor;await save();applyAppearance();if(page==='settings')render()},
 'business-form':async d=>{db.settings.companyName=d.companyName;db.settings.companyPhone=d.companyPhone;db.settings.companyAddress=d.companyAddress;db.settings.taxId=d.taxId;db.settings.invoiceAccent=d.invoiceAccent;db.settings.invoiceTitle=d.invoiceTitle},
 'password-form':async d=>{if(!await checkPassword(d.currentPassword))throw Error('رمز فعلی درست نیست.');if(d.newPassword.length<8)throw Error('رمز جدید باید دست‌کم ۸ نویسه باشد.');if(d.newPassword!==d.confirmPassword)throw Error('تکرار رمز جدید یکسان نیست.');const h=await makePasswordHash(d.newPassword);db.settings.authSalt=h.salt;db.settings.authHash=h.hash;db.settings.mustChangePassword=false;sessionStorage.setItem('hawraz_unlocked','yes')} 
 };
 Object.entries(handlers).forEach(([id,fn])=>{const f=$(id);if(!f)return;if(id==='settings-form'){['currency','lowStock','language','theme','mode','background','iconStyle','layout','invoiceTemplate','calendarType','dateOrder','navPosition','navSide','fontScale','iconScale','clockStyle','clockPosition','clockColor'].forEach(k=>{if(f.elements[k])f.elements[k].value=db.settings[k]??EMPTY.settings[k];if(f.elements.clockVisible)f.elements.clockVisible.checked=db.settings.clockVisible!==false})}if(id==='business-form'){['companyName','companyPhone','taxId','companyAddress','invoiceAccent','invoiceTitle'].forEach(k=>{if(f.elements[k])f.elements[k].value=db.settings[k]||''})}f.onsubmit=async e=>{e.preventDefault();try{await fn(formData(f));await save();toast('با موفقیت ذخیره شد.');editId=null;render()}catch(err){toast(err.message||'خطا در ذخیره اطلاعات')}}});
 $('backup2')?.addEventListener('click',backup);$('backup-encrypted')?.addEventListener('click',encryptedBackup);$('restore')?.addEventListener('change',restore);
 $('reset-entire-app')?.addEventListener('click',async()=>{if(!confirm('هشدار: تمام اطلاعات و تنظیمات این برنامه برای همیشه از این دستگاه پاک می‌شود. ادامه می‌دهی؟'))return;const phrase=prompt('برای تأیید نهایی دقیقاً بنویس: حذف همه اطلاعات');if(phrase!=='حذف همه اطلاعات')return toast('عبارت تأیید مطابقت نداشت؛ هیچ اطلاعاتی حذف نشد.');try{backup();const fresh=structuredClone(EMPTY);const h=await makePasswordHash('123454321');fresh.settings.authSalt=h.salt;fresh.settings.authHash=h.hash;fresh.settings.mustChangePassword=true;fresh.settings.authFailedCount=0;fresh.settings.authLockedUntil=0;db=fresh;await save();sessionStorage.removeItem('hawraz_unlocked');toast('برنامه به حالت اولیه برگشت. رمز پیش‌فرض 123454321 است؛ هنگام ورود باید آن را تغییر بدهی.');renderLock()}catch(err){toast('ریست کامل نشد: '+(err.message||'خطای ذخیره‌سازی'))}});
}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function backup(){const payload={format:'HAWRAZ_LOCAL_BACKUP',version:1,createdAt:new Date().toISOString(),data:db};download(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),`HAWRAZ-backup-${today()}.json`);toast('فایل پشتیبان ساخته شد.')}
async function encryptedBackup(){if(!crypto.subtle)return toast('رمزگذاری در این محیط پشتیبانی نمی‌شود.');const pass=prompt('برای رمزگذاری پشتیبان یک گذرواژه قوی وارد کن:');if(!pass||pass.length<10)return toast('گذرواژه باید حداقل ۱۰ نویسه باشد.');const enc=new TextEncoder(),salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12));const material=await crypto.subtle.importKey('raw',enc.encode(pass),'PBKDF2',false,['deriveKey']);const key=await crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:250000,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['encrypt']);const plain=enc.encode(JSON.stringify({format:'HAWRAZ_LOCAL_BACKUP',version:1,createdAt:new Date().toISOString(),data:db}));const cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,plain);const pack={format:'HAWRAZ_ENCRYPTED_BACKUP',version:1,salt:Array.from(salt),iv:Array.from(iv),cipher:Array.from(new Uint8Array(cipher))};download(new Blob([JSON.stringify(pack)],{type:'application/json'}),`HAWRAZ-encrypted-${today()}.json`);toast('پشتیبان رمزگذاری‌شده ساخته شد؛ گذرواژه را گم نکن.')}
async function decryptBackup(pack,pass){const enc=new TextEncoder(),salt=new Uint8Array(pack.salt),iv=new Uint8Array(pack.iv),cipher=new Uint8Array(pack.cipher);const material=await crypto.subtle.importKey('raw',enc.encode(pass),'PBKDF2',false,['deriveKey']);const key=await crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:250000,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['decrypt']);const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv},key,cipher);return JSON.parse(new TextDecoder().decode(plain))}

async function restore(e){const f=e.target.files[0];if(!f)return;try{let x=JSON.parse(await f.text());if(x.format==='HAWRAZ_ENCRYPTED_BACKUP'){const pass=prompt('گذرواژه پشتیبان را وارد کن:');if(!pass)throw Error('گذرواژه وارد نشد.');x=await decryptBackup(x,pass)}if(x.format!=='HAWRAZ_LOCAL_BACKUP'||!x.data||!Array.isArray(x.data.products)||!Array.isArray(x.data.customers)||!Array.isArray(x.data.orders))throw Error('ساختار فایل پشتیبان معتبر نیست.');if(!confirm('تمام اطلاعات فعلی این دستگاه با فایل پشتیبان جایگزین شود؟ ابتدا از اطلاعات فعلی پشتیبان گرفته‌ای؟'))return;backup();db={...structuredClone(EMPTY),...x.data};await save();toast('بازیابی انجام شد.');render()}catch(err){toast(err.message)}finally{e.target.value=''}}
function csv(kind){const rows=kind==='orders'?[['code','customer','title','quantity','total','status','dueDate'],...db.orders.map(o=>[o.code,db.customers.find(c=>c.id===o.customerId)?.name,o.title,o.quantity,o.total,o.status,o.dueDate])]:[['name','phone','address','orders','balance'],...db.customers.map(c=>[c.name,c.phone,c.address,customerOrders(c.id).length,customerBalance(c.id)])];const content='\\ufeff'+rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\\r\\n');download(new Blob([content],{type:'text/csv;charset=utf-8'}),`HAWRAZ-${kind}-${today()}.csv`)}
$('backup').onclick=backup;$('logout')?.addEventListener('click',lockApp);$('printCurrent')?.addEventListener('click',printCurrent);
if(!window.__HAWRAZ_INIT_STARTED){window.__HAWRAZ_INIT_STARTED=true;init().catch(e=>{console.error('HAWRAZ startup failed:',e);const msg=document.createElement('div');msg.className='notice';msg.style.cssText='margin:24px;padding:18px;white-space:pre-wrap';msg.textContent='برنامه نتوانست راه‌اندازی شود. آن را با همان روش اجرای آفلاین قبلی باز کن.\nجزئیات فنی: '+(e&&e.message?e.message:String(e));document.body.appendChild(msg);});}
